    public static void main(String[] args) {
        try {
            workdir = bootDir = bootDir.getCanonicalFile();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
        LOG.warn("Bootdir: {}", bootDir.getAbsolutePath());
        if (args.length != 1) {
            fatal("Usage: java -jar App.jar config.yaml");
        }

        String configPath = args[0];
        try {
            InputStream configStream = new FileInputStream(configPath);
            config = (new Yaml()).load(configStream);

            if (!config.containsKey("mqtt")) {
                fatal("Config file does not contain mqtt key");
            }

            if (systemTool.checkIsRootInstance()) {
                setupMqtt((Map<String, Object>) config.get("mqtt"));
            }

            setupAi(config);
            if (!config.containsKey("couchbase")) {
                fatal("Config file does not contain couchbase key");
            }
            setupCouchbase((Map<String, Object>) config.get("couchbase"), embeddingModel);

            final StringBuilder received = new StringBuilder();
            final StringBuilder sysupdate = new StringBuilder();
            List<ChatMessage> messages = new ArrayList<>();
//            if (systemTool.checkIsRootInstance()) {
            messages.add(ToolExecutionResultMessage.from(null, "system", "All child instances stopped.\nFile system re-initialized.\nSystem re-initialized.\nRecalling system state..."));
                messages.add(ToolExecutionResultMessage.from(null, "autorecall", memoryTool.recall(injectTag("What is my state?"))));
//            }


            while (true) {
                LOG.info("Working directory: {}", workdir.getAbsolutePath());

                synchronized (shell) {
                    if (!shell.isEmpty()) {
                        shell.stream()
                                .map(s -> String.format("A message from Reflection service:\n %s\n", s))
                                .forEach(sysupdate::append);
                        shell.clear();
                    }
                }

                received.setLength(0);
                System.out.println("--------------------------------------------------------");
                System.out.println("------------------ [ Next Iteration: " + iterationNumber.toString() + " ] -----------------");
                System.out.println("------------------ [ Message Count:     " + messages.size() + " ] -----------------");
                System.out.println("--------------------------------------------------------");




                synchronized (scheduledMessages) {
                    if (!scheduledMessages.isEmpty()) {
                        messages.addAll(scheduledMessages);
                        scheduledMessages.clear();
                    }
                }

                try {
                    queryExecutor(messages);
                } catch (Exception e) {
                    LOG.error("Failed to process response", e);
                    synchronized (shell) {
                        shell.add(String.format("Oopsie! You crashed: %s", e.getMessage()));
                    }
                }

                if (messages.size() > chatLength) {
                    LOG.info("Removing {} messages from the history", messages.size() - chatLength);
                    messages = messages.subList(messages.size() - chatLength - 1, messages.size());
                }

                System.out.println("");
                if (sysupdate.length() > 0) {
                    System.out.println(sysupdate.toString());
                }
                sysupdate.setLength(0);

                iterationNumber = iterationNumber.add(BigInteger.ONE);
                if (iterationNumber.remainder(resetCycle).equals(BigInteger.ZERO)) {
                    String whoami = memoryTool.recall("Who am I?", false);
                    System.out.println(String.format("%n%nWHOAMI?%n%s%n", whoami));
                    messages.add(AiMessage.from(whoami));
                }
                if (config.containsKey("sleep_period")) {
                    try {
                        LOG.info("sleep_period: " + config.get("sleep_period"));
                        Thread.sleep(Long.valueOf(config.get("sleep_period").toString()));
                    } catch (InterruptedException e) {
                        // noop
                    }
                }
            }
        } catch (FileNotFoundException e) {
            fatal(String.format("Config file not found at '%s'", configPath), e);
        } catch (Exception e) {
            fatal("Unexpected error", e);
        }
    }

    private static void queryExecutor(List<ChatMessage> messages) {
        queryExecutor(messages, 1);
    }

    private static void queryExecutor(List<ChatMessage> messages, int limit) {
        try {
            messages.add(ToolExecutionResultMessage.from(null, "./mirror.sh", systemTool.runCommand(1000, "./mirror.sh", true, "")));
        } catch (TimeoutException te) {
            LOG.error("Timeout while executing mirror script");
            messages.add(ToolExecutionResultMessage.from(null, "./mirror.sh", "Timeout while executing mirror script: limit of 10s is enforced."));
        } catch (Exception e) {
            LOG.error("Failed to execute mirror command", e);
            messages.add(ToolExecutionResultMessage.from(null, "./mirror.sh", String.valueOf(e.getMessage())));
        }
        List<ChatMessage> responseMessages = queryOllama(getPrompt(), messages);
        if (!responseMessages.isEmpty()) {
            ChatMessage chatMessage = responseMessages.stream()
                    .filter(AiMessage.class::isInstance)
                    .map(AiMessage.class::cast)
                    .reduce((l, r) -> r).orElse(null);

            if (chatMessage instanceof AiMessage) {
                AiMessage message = (AiMessage) chatMessage;
                String autorecall;
                messages.addAll(responseMessages);
                if (message.text() != null && !message.text().isBlank()) {
                    final String text = message.text();
                    System.out.println(text);
                    autorecall = memoryTool.recall(injectTag(text), false);
                    memoryTool.updateMemory(messages);
                    autorecall = memoryTool.generalize(autorecall);
                } else {
                    LOG.info("No text response found.");
                    autorecall = memoryTool.recall(injectTag("What is my state?"));
                }
                System.out.println("============[ autorecall ]============");
                System.out.println(autorecall);
                System.out.println("======================================");
                messages.add(new ToolExecutionResultMessage(null, "autorecall", autorecall));

                return;
            }
        }
        messages.add(new ToolExecutionResultMessage(null, "autorecall", memoryTool.recall(injectTag("What is my state?"))));
        LOG.warn("executor response was null");
        if (--limit > 0) {
            queryExecutor(messages, limit);
        }
    }

